constexpr float kMinBaseFontSize = 10.0f;
constexpr float kMaxBaseFontSize = 32.0f;

float ScaleFromBase(float value, float baseFontSize) {
    return value * (ClampBaseFontSize(baseFontSize) / kDefaultBaseFontSize);
