static void PostProcessMath(DocumentModel& model) {
    std::function<void(Block&)> recurse = [&](Block& block) {
        if (!block.inlineRuns.empty()) {
            std::vector<InlineRun> newRuns;
            for (auto& run : block.inlineRuns) {
                if (run.kind != InlineKind::Text || 
                    HasFormatting(run.formatting, InlineFormatting::Math) ||
                    HasFormatting(run.formatting, InlineFormatting::Code) ||
                    HasFormatting(run.formatting, InlineFormatting::Keyboard) ||
                    run.kind == InlineKind::Image) {
                    newRuns.push_back(std::move(run));
                    continue;
                }

                std::string_view text = run.text;
                size_t currentPos = 0;

                while (currentPos < text.size()) {
                    size_t nextDollar = text.find('$', currentPos);
                    if (nextDollar == std::string_view::npos) {
                        if (currentPos < text.size()) {
                            newRuns.push_back(InlineRun{
                                .formatting = run.formatting,
                                .kind = InlineKind::Text,
                                .text = std::string(text.substr(currentPos)),
                            });
                        }
                        break;
                    }

                    if (nextDollar > currentPos) {
                        newRuns.push_back(InlineRun{
                            .formatting = run.formatting,
                            .kind = InlineKind::Text,
                            .text = std::string(text.substr(currentPos, nextDollar - currentPos)),
                        });
                    }

                    size_t closingDollar = text.find('$', nextDollar + 1);
                    if (closingDollar == std::string_view::npos) {
                        newRuns.push_back(InlineRun{
                            .formatting = run.formatting,
                            .kind = InlineKind::Text,
                            .text = std::string(text.substr(nextDollar)),
                        });
                        break;
                    }

                    newRuns.push_back(InlineRun{
                        .formatting = run.formatting | InlineFormatting::Math,
                        .kind = InlineKind::Text,
                        .text = std::string(text.substr(nextDollar + 1, closingDollar - nextDollar - 1)),
                    });

                    currentPos = closingDollar + 1;
                }
            }
            block.inlineRuns = std::move(newRuns);
        }

        for (auto& child : block.children) {
            recurse(child);
        }
    };

    for (auto& block : model.blocks) {
        recurse(block);
    }
}

